const {dayTasks,startDayTask,saveTaskResult}=await import(`data:text/javascript;base64,${Buffer.from(dayBuild.outputFiles[0].text).toString('base64')}`);
test('my day includes blocked and completed planned steps but excludes archived, cancelled and other days',()=>{const base={id:'one',title:'English',category:'Learning',done:false,archived:false,plannedDate:'2026-10-25'};assert.deepEqual(dayTasks([base,{...base,id:'blocked',status:'blocked'},{...base,id:'done',done:true},{...base,id:'archived',archived:true},{...base,id:'cancelled',status:'cancelled'},{...base,id:'other',plannedDate:'2026-10-26'}],'2026-10-25').map(x=>x.id),['one','blocked','done']);});
test('starting a day step atomically links the timer and uses its estimate without completing the task',()=>{const task={id:'one',title:'English',category:'Learning',done:false,archived:false,plannedDate:'2026-10-25',estimate:15};const data={'personal-os.tasks.v1':[task]};const next=startDayTask(data,'one','2026-10-25',1000);assert.equal(next['personal-os.focus.v1'].remaining,900);assert.equal(next['personal-os.focus.v1'].taskId,'one');assert.equal(next['personal-os.tasks.v1'][0].status,'doing');assert.equal(next['personal-os.tasks.v1'][0].done,false);assert.equal(task.status,undefined);assert.throws(()=>startDayTask(next,'one','2026-10-25',2000),/active-focus/);assert.throws(()=>startDayTask(data,'one','2026-10-24'),/unavailable-task/);});
test('recording a result preserves task state; explicit completion is separate and stale edits fail',()=>{const task={id:'one',title:'English',category:'Learning',done:false,archived:false,revision:'current'};const data={'personal-os.tasks.v1':[task]};const next=saveTaskResult(data,task,'  Practiced five sentences  ','2026-10-24',false,'2026-10-24');assert.deepEqual(next['personal-os.tasks.v1'][0].result,{note:'Practiced five sentences',date:'2026-10-24'});assert.equal(next['personal-os.tasks.v1'][0].done,false);assert.equal(saveTaskResult(data,task,'Done','2026-10-24',true,'2026-10-24')['personal-os.tasks.v1'][0].status,'done');assert.throws(()=>saveTaskResult(data,{...task,revision:'stale'},'Lost edit','2026-10-24',false,'2026-10-24'),/edit-conflict/);assert.throws(()=>saveTaskResult(data,task,'Future','2026-10-25',false,'2026-10-24'),/invalid-result/);assert.throws(()=>saveTaskResult(data,task,'Invalid','2026-02-30',false,'2026-10-24'),/invalid-result/);});
const weekBuild=await build({entryPoints:['src/features/planner/weekModel.ts'],bundle:true,platform:'node',format:'esm',write:false});
