test('weeks align to Monday across month and year boundaries',()=>{assert.equal(weekStart('2027-01-03'),'2026-12-28');assert.equal(weekDates('2026-12-28')[6],'2027-01-03');});
test('weekly rollover moves only unfinished non-archived source-week tasks and keeps deadlines',()=>{
 const all=[{id:'open',plannedDate:'2026-10-21',dueDate:'2026-10-22',goalId:'g',done:false},{id:'done',plannedDate:'2026-10-21',done:true},{id:'archive',plannedDate:'2026-10-21',archived:true},{id:'next',plannedDate:'2026-10-28'},{id:'free'}];const result=rolloverTasks(all,'2026-10-19','2026-10-26');assert.equal(result[0].plannedDate,'2026-10-28');assert.equal(result[0].dueDate,'2026-10-22');assert.equal(result[0].goalId,'g');assert.deepEqual(result.slice(1),all.slice(1));assert.equal(all[0].plannedDate,'2026-10-21');
});
test('day load combines task estimates and events and explicitly counts unknown durations',()=>{
 const load=dayLoad([{plannedDate:'2026-10-24',estimate:90},{plannedDate:'2026-10-24'},{plannedDate:'2026-10-24',estimate:500,archived:true}],[{kind:'event',date:'2026-10-24',time:'10:00',durationMinutes:30},{kind:'event',date:'2026-10-24',time:'12:00'}],'2026-10-24',120);assert.equal(load.total,180);assert.equal(load.overloaded,true);assert.equal(load.unknownTasks,1);assert.equal(load.estimatedEvents,1);
});
test('weeks have three independent outcomes and separate reflection objects',()=>{
 const a=emptyWeek();const b=emptyWeek();a.outcomes[0].title='changed';a.review.wins='done';assert.equal(b.outcomes[0].title,'');assert.equal(b.review.wins,'');assert.equal(a.outcomes.length,3);assert.equal(a.outcomes[1].title,'');
});
const goalBuild=await build({entryPoints:['src/features/life/goalModel.ts'],bundle:true,platform:'node',format:'esm',write:false});
const {goalStats,replaceGoalTasks}=await import(`data:text/javascript;base64,${Buffer.from(goalBuild.outputFiles[0].text).toString('base64')}`);
