const storageBuild=await build({entryPoints:['src/lib/storageCore.ts'],bundle:true,platform:'node',format:'esm',write:false});
const {STORE_KEY,readStore,commit,makeBackup,parseBackup,storageToken,restoreSnapshot}=await import(`data:text/javascript;base64,${Buffer.from(storageBuild.outputFiles[0].text).toString('base64')}`);
function memoryStorage(initial={}){const values=new Map(Object.entries(initial));return {getItem:k=>values.get(k)??null,setItem:(k,v)=>values.set(k,v),values};}
test('legacy migration preserves all existing data and links in one write',()=>{const tasks=[task('linked',{goalId:'g',milestoneId:'m',archived:true})];const s=memoryStorage({'personal-os.tasks.v1':JSON.stringify(tasks)});const old=readStore(s);const next=commit(s,old.revision,{...old.data,'personal-os.language':'ar'});assert.deepEqual(readStore(s).data['personal-os.tasks.v1'],tasks);assert.equal(next.version,3);assert.ok(s.getItem('personal-os.tasks.v1'));});
test('corrupt saved JSON and invalid shapes are never overwritten',()=>{for(const raw of ['{broken','{"version":3,"revision":"r","data":{"personal-os.tasks.v1":[{}]}}']){const s=memoryStorage({[STORE_KEY]:raw});assert.throws(()=>readStore(s));assert.throws(()=>commit(s,'r',{}));assert.equal(s.getItem(STORE_KEY),raw);}});
test('stale tab revision cannot overwrite more recent changes',()=>{const s=memoryStorage();const first=readStore(s);commit(s,first.revision,{'personal-os.language':'ar'});assert.throws(()=>commit(s,first.revision,{'personal-os.language':'en'}),/conflict/);assert.equal(readStore(s).data['personal-os.language'],'ar');});
test('quota failure leaves previous complete snapshot untouched',()=>{const s=memoryStorage();commit(s,'legacy',{'personal-os.dark':true});const raw=s.getItem(STORE_KEY);const broken={getItem:s.getItem,setItem:()=>{throw Error('quota');}};assert.throws(()=>commit(broken,readStore(s).revision,{}));assert.equal(s.getItem(STORE_KEY),raw);});
test('backup roundtrip preserves archives, links, conversations and weekly outcomes',()=>{const d={'personal-os.tasks.v1':[task('a',{goalId:'g',milestoneId:'m',archived:true})],'personal-os.entries.v1':restoreWorkspace(null,[]),'personal-os.weeks.v1':{'2026-10-19':emptyWeek()},'personal-os.conversations.v1':[{id:'c',title:'Chat',archived:true,messages:[{id:'msg',role:'user',text:'Hello'}]}]};assert.deepEqual(parseBackup(JSON.stringify(makeBackup(d))),d);});
test('unsupported backups and unsafe task collections are rejected',()=>{for(const backup of [{format:'other',version:1,data:{}},{format:'personal-os-backup',version:99,data:{}},{format:'personal-os-backup',version:1,exportedAt:'now',data:{'personal-os.tasks.v1':[task('duplicate'),task('duplicate')]}},{format:'personal-os-backup',version:1,exportedAt:'now',data:{'personal-os.tasks.v1':[{}]}}])assert.throws(()=>parseBackup(JSON.stringify(backup)));});

test('restoration replaces the whole snapshot and survives reopening',()=>{const s=memoryStorage();commit(s,'legacy',{'personal-os.tasks.v1':[task('old')]});const target={'personal-os.tasks.v1':[task('restored',{archived:true,goalId:'g'})],'personal-os.language':'ar'};restoreSnapshot(s,parseBackup(JSON.stringify(makeBackup(target))),storageToken(s));assert.deepEqual(readStore(s).data,target);});
test('restore preview cannot overwrite changes made after preview',()=>{const s=memoryStorage();const token=storageToken(s);commit(s,'legacy',{'personal-os.dark':true});assert.throws(()=>restoreSnapshot(s,{},token),/conflict/);assert.equal(readStore(s).data['personal-os.dark'],true);});
test('explicit valid restoration repairs corruption, but failed writes retain original bytes',()=>{const s=memoryStorage({[STORE_KEY]:'corrupt-original'});const token=storageToken(s);assert.throws(()=>restoreSnapshot({getItem:s.getItem,setItem:()=>{throw Error('quota');}},{},token));assert.equal(s.getItem(STORE_KEY),'corrupt-original');restoreSnapshot(s,{'personal-os.language':'ar'},token);assert.equal(readStore(s).data['personal-os.language'],'ar');});
const captureBuild=await build({entryPoints:['src/features/capture/model.ts'],bundle:true,platform:'node',format:'esm',write:false});
const {parseCapture,captureErrors,applyCapture}=await import(`data:text/javascript;base64,${Buffer.from(captureBuild.outputFiles[0].text).toString('base64')}`);
const captureSource={text:'Original multi item request',batchId:'test-batch',createdAt:'2026-10-24T10:00:00.000Z'};
test('capture saves goal links and estimates with the planned day',()=>{const x=parseCapture('Task: Practice 2026-10-25');x[0].goalId='english';x[0].estimate=15;const data={'personal-os.entries.v1':restoreWorkspace(null,[])};data['personal-os.entries.v1'].entries.push({id:'english',kind:'goal',title:'English',area:'Learning',detail:'',date:'',time:'',progress:0,archived:false,doneDates:[]});const saved=applyCapture(data,x,captureSource)['personal-os.tasks.v1'][0];assert.equal(saved.goalId,'english');assert.equal(saved.estimate,15);assert.equal(saved.plannedDate,'2026-10-25');assert.equal(saved.dueDate,undefined);});
test('capture rejects unavailable goals and invalid task estimates atomically',()=>{const x=parseCapture('Task: Practice');x[0].goalId='missing';assert.throws(()=>applyCapture({},x,captureSource),/unavailable-goal/);delete x[0].goalId;for(const estimate of [-1,NaN,1441]){x[0].estimate=estimate;assert.throws(()=>applyCapture({},x,captureSource),/invalid-estimate/);}});
test('Arabic compound requests become reviewable task, appointment and idea',()=>{const x=parseCapture('أراجع المشروع بكرة، وعندي موعد الخميس، وفكرة عايز أحفظها','2026-10-24');assert.equal(x.length,3);assert.deepEqual(x.map(i=>i.kind),['task','event','note']);assert.equal(x[0].date,'2026-10-25');assert.equal(x[1].date,'');assert.equal(x[1].time,'');assert.equal(captureErrors(x),true);assert.match(x[0].title,/أراجع/);});
test('English input and explicit dates parse without manufacturing times',()=>{const x=parseCapture('Task: Review tomorrow; Event: Review 2026-11-02 14:00; Idea: a simple board','2026-12-31');assert.equal(x[0].date,'2027-01-01');assert.equal(x[1].date,'2026-11-02');assert.equal(x[1].time,'14:00');assert.equal(x[2].kind,'note');assert.equal(captureErrors(x),false);});
test('ordinary commas do not split a single thought; unclear text starts as a note',()=>{assert.equal(parseCapture('ملاحظة: ألوان هادئة، وخط أكبر').length,1);assert.equal(parseCapture('Something I may do someday')[0].kind,'note');});
test('invalid dates, missing times, empty titles and oversized batches are blocked',()=>{for(const text of ['Event: review 2026-02-30 14:00','موعد: مراجعة بكرة','Routine: Walk','Task: '])assert.equal(captureErrors(parseCapture(text)),true);assert.throws(()=>parseCapture(Array.from({length:21},()=> 'Note: item').join('\n')));});
test('capture transaction keeps original source, links and unrelated records',()=>{const data={'personal-os.tasks.v1':[task('old',{goalId:'g',milestoneId:'m'})],'personal-os.entries.v1':restoreWorkspace(null,[])};const x=parseCapture('Task: Review tomorrow\nNote: idea','2026-10-24');const result=applyCapture(data,x,captureSource);assert.deepEqual(result['personal-os.tasks.v1'][0],data['personal-os.tasks.v1'][0]);assert.equal(result['personal-os.tasks.v1'][1].plannedDate,'2026-10-25');assert.equal(result['personal-os.tasks.v1'][1].dueDate,undefined);assert.equal(result['personal-os.tasks.v1'][1].source.text,captureSource.text);assert.equal(result['personal-os.entries.v1'].entries.at(-1).source.fragment,'Note: idea');assert.equal(data['personal-os.tasks.v1'].length,1);});
test('repeated confirmation preserves the same IDs even if a retry changes type',()=>{const x=parseCapture('Task: Review\nNote: Idea');const once=applyCapture({},x,captureSource);const twice=applyCapture(once,x.map(i=>({...i,kind:'event',date:'2026-10-24',time:'14:00'})),captureSource);assert.deepEqual(twice,once);});
test('failed batch writes save neither tasks nor notes and retry saves both once',()=>{const s=memoryStorage();const initial=readStore(s);const x=parseCapture('Task: Review\nNote: Idea');const update=applyCapture(initial.data,x,captureSource);assert.throws(()=>commit({getItem:s.getItem,setItem:()=>{throw Error('quota');}},initial.revision,update));assert.deepEqual(readStore(s).data,{});commit(s,initial.revision,update);const loaded=readStore(s);commit(s,loaded.revision,applyCapture(loaded.data,x,captureSource));assert.equal(readStore(s).data['personal-os.tasks.v1'].length,1);assert.equal(readStore(s).data['personal-os.entries.v1'].entries.filter(e=>e.source).length,1);});
test('notes retain temporal words and clock times as content',()=>{const x=parseCapture('فكرة: تقليل خطوات تسجيل اليوم 14:00','2026-10-24')[0];assert.equal(x.title,'تقليل خطوات تسجيل اليوم 14:00');assert.equal(x.date,'');assert.equal(x.time,'');});
