test('appointment conflicts include containment, exclude touching endpoints and flag estimated durations',()=>{const all=[event('long','10:00',120),event('inside','10:30',30),event('touch','12:00',30)];const conflicts=eventConflicts(all,'2026-10-24');assert.equal(conflicts.length,1);assert.equal(conflicts[0].minutes,30);assert.equal(eventConflicts([event('unknown','10:00',undefined),event('other','10:30',30)])[0].estimated,true);});
