test('missing event details block the entire batch and stale or cancelled previews cannot execute',()=>{const {message,data}=batchChat('Task: Review; Event: Meeting; Note: Feedback');assert.throws(()=>confirmBatch(data,'batch-chat',message),/invalid-capture/);assert.equal(data['personal-os.tasks.v1'],undefined);const valid=batchChat();assert.throws(()=>confirmBatch(valid.data,'batch-chat',{...valid.message,batch:valid.message.batch.slice(1)}),/stale-preview/);valid.message.status='cancelled';assert.throws(()=>confirmBatch(valid.data,'batch-chat',valid.message),/stale-preview/);});
test('review edits, exclusions, scoped context and archived conversations are respected',()=>{const {message,data}=batchChat();message.scope='context:Product';message.batch=message.batch.filter(x=>x.kind!=='task');message.batch[0].time='15:30';message.batch[1].title='Edited note';const next=confirmBatch(data,'batch-chat',message);assert.equal(next['personal-os.tasks.v1'].length,0);assert.equal(next['personal-os.entries.v1'].entries[0].time,'15:30');assert.equal(next['personal-os.entries.v1'].entries[1].title,'Edited note');assert.equal(next['personal-os.entries.v1'].entries[1].context,'Product');data['personal-os.conversations.v1'][0].archived=true;assert.throws(()=>confirmBatch(data,'batch-chat',message),/unavailable-conversation/);});
test('batch failures preserve storage and permanent forgetting removes associated batch messages',()=>{const {message,data}=batchChat();const s=memoryStorage();const initial=readStore(s);commit(s,initial.revision,data);const current=readStore(s);assert.throws(()=>commit({getItem:s.getItem,setItem:()=>{throw Error('quota');}},current.revision,confirmBatch(current.data,'batch-chat',message)));assert.equal(readStore(s).data['personal-os.conversations.v1'][0].messages[1].status,'pending');const saved=confirmBatch(data,'batch-chat',message);const item=saved['personal-os.tasks.v1'][0];const removed=auditWorkspace(saved,{...saved,'personal-os.tasks.v1':[]});const record=removed['personal-os.trash.v1'][0];const forgotten=forgetRecord(removed,record.id);assert.equal(forgotten['personal-os.conversations.v1'][0].messages.length,0);assert.equal(forgotten['personal-os.entries.v1'].entries[0].source,undefined);assert.equal(item.id.startsWith('capture-assistant-'),true);});


