test('undo atomically soft-deletes unchanged batch targets and records the result without replay',()=>{const data=executedBatch();const preview=undoPreview(data,'batch-chat','batch-message');assert.equal(preview.rows.filter(x=>x.state==='safe').length,3);const result=auditWorkspace(data,undoAction(data,preview),'2026-10-25T10:02:00Z');assert.equal(result['personal-os.tasks.v1'].length,0);assert.equal(result['personal-os.entries.v1'].entries.length,0);assert.equal(result['personal-os.trash.v1'].length,3);const message=result['personal-os.conversations.v1'][0].messages[1];assert.equal(message.status,'reverted');assert.equal(message.undo.removedIds.length,3);assert.throws(()=>undoAction(result,preview),/unavailable-action/);assert.deepEqual(parseBackup(JSON.stringify(makeBackup(result))),JSON.parse(JSON.stringify(result)));});
test('undo preserves edits, archives and missing targets and never touches unrelated records',()=>{const data=executedBatch();const item=data['personal-os.tasks.v1'][0];const changed=auditWorkspace(data,{...data,'personal-os.tasks.v1':[{...item,title:'User changed this'}]},'2026-10-25T10:02:00Z');changed['personal-os.entries.v1'].entries[0].history.push({at:'later',fields:['archived']});changed['personal-os.entries.v1'].entries[0].archived=true;changed['personal-os.entries.v1'].entries=changed['personal-os.entries.v1'].entries.slice(0,1);const preview=undoPreview(changed,'batch-chat','batch-message');assert.deepEqual(preview.rows.map(x=>x.state),['edited','edited','missing']);assert.throws(()=>undoAction(changed,preview),/nothing-to-undo/);});
test('partial undo keeps edited targets while safely removing unchanged siblings',()=>{const data=executedBatch();const item=data['personal-os.tasks.v1'][0];const changed=auditWorkspace(data,{...data,'personal-os.tasks.v1':[{...item,done:true,status:'done'},task('unrelated')]});const preview=undoPreview(changed,'batch-chat','batch-message');const result=undoAction(changed,preview);assert.equal(result['personal-os.tasks.v1'].length,2);assert.equal(result['personal-os.tasks.v1'][0].done,true);assert.equal(result['personal-os.entries.v1'].entries.length,0);assert.equal(result['personal-os.conversations.v1'][0].messages[1].undo.keptIds.length,1);});
test('new dependencies and focus references protect targets and invalidate an older undo preview',()=>{const data=executedBatch();const before=undoPreview(data,'batch-chat','batch-message');const note=data['personal-os.entries.v1'].entries.find(x=>x.kind==='note');const linked={...data,'personal-os.tasks.v1':[...data['personal-os.tasks.v1'],task('dependent',{memoryId:note.id})]};assert.equal(undoPreview(linked,'batch-chat','batch-message').rows.find(x=>x.id===note.id).state,'linked');assert.throws(()=>undoAction(linked,before),/stale-undo/);const timer={...data,'personal-os.focus.v1':{ends:null,remaining:1500,taskId:data['personal-os.tasks.v1'][0].id}};assert.equal(undoPreview(timer,'batch-chat','batch-message').rows[0].state,'linked');});
test('undo rejects edits after preview and treats legacy items without creation history conservatively',()=>{const data=executedBatch();const before=undoPreview(data,'batch-chat','batch-message');const changed=auditWorkspace(data,{...data,'personal-os.tasks.v1':data['personal-os.tasks.v1'].map(x=>({...x,description:'New work'}))});assert.throws(()=>undoAction(changed,before),/stale-undo/);const legacy=executedBatch();delete legacy['personal-os.tasks.v1'][0].history;assert.equal(undoPreview(legacy,'batch-chat','batch-message').rows[0].state,'edited');});
test('undo handles legacy single actions and failed writes keep all records and action status',()=>{const message={id:'single',role:'assistant',text:'Saved',proposal:{kind:'task',title:'Test',date:'',time:''},status:'confirmed',targetId:'one'};const data=auditWorkspace({},{'personal-os.tasks.v1':[task('one')],'personal-os.conversations.v1':[{id:'single-chat',title:'Single',archived:true,messages:[message]}]});const preview=undoPreview(data,'single-chat','single');const storage=memoryStorage();commit(storage,readStore(storage).revision,data);const current=readStore(storage);assert.throws(()=>commit({getItem:storage.getItem,setItem:()=>{throw Error('quota');}},current.revision,undoAction(current.data,preview)));assert.equal(readStore(storage).data['personal-os.tasks.v1'].length,1);assert.equal(readStore(storage).data['personal-os.conversations.v1'][0].messages[0].status,'confirmed');});
